internal sealed class ToggleSwitch:Control
{
    public bool Checked;public event EventHandler? Changed;
    public ToggleSwitch(){DoubleBuffered=true;Cursor=Cursors.Hand;TabStop=true;AccessibleRole=AccessibleRole.CheckButton;}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;Visual.Round(e.Graphics,new Rectangle(0,2,40,20),Checked?Visual.Lilac:Visual.Stroke,10);using var b=new SolidBrush(Checked?Color.White:Visual.Muted);e.Graphics.FillEllipse(b,Checked?22:3,5,14,14);}
    internal void TestToggle()=>OnClick(EventArgs.Empty);
    protected override void OnClick(EventArgs e){Checked=!Checked;Changed?.Invoke(this,EventArgs.Empty);Invalidate();base.OnClick(e);}
    protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Space){OnClick(EventArgs.Empty);e.Handled=true;}base.OnKeyDown(e);}
}
